package main

import (
	"log"
	"net/http"
	nethttppprof "net/http/pprof"
	"os"
	"os/signal"
	"runtime"
	"syscall"
)

func main() {
	// 1) block/mutex 默认关闭，启动时设保守采样率避免全采开销。
	// block rate=10000 表示 profiler 目标是平均每累计 10μs 阻塞时间采一个样本，
	// 不是 10μs 阈值。rate=1 近似全采，诊断窗口要短。
	runtime.SetBlockProfileRate(10000)
	// mutex fraction=100 粗采，平均每 100 次竞争采一次，
	// 先定位热点锁，再通过 SIGUSR1 切到 fraction=1 精采。
	runtime.SetMutexProfileFraction(100)

	// 2) SIGUSR1 动态切换到精采模式，SIGUSR2 恢复保守采样。
	go func() {
		ch := make(chan os.Signal, 1)
		signal.Notify(ch, syscall.SIGUSR1, syscall.SIGUSR2)
		for sig := range ch {
			if sig == syscall.SIGUSR1 {
				runtime.SetBlockProfileRate(1)
				runtime.SetMutexProfileFraction(1)
			} else {
				runtime.SetBlockProfileRate(10000)
				runtime.SetMutexProfileFraction(100)
			}
		}
	}()

	// 3) pprof 走独立 admin mux，避免和业务路由共用。
	admin := http.NewServeMux()
	admin.HandleFunc("/debug/pprof/", auth(nethttppprof.Index))
	admin.HandleFunc("/debug/pprof/cmdline", auth(nethttppprof.Cmdline))
	admin.HandleFunc("/debug/pprof/profile", auth(nethttppprof.Profile))
	admin.HandleFunc("/debug/pprof/symbol", auth(nethttppprof.Symbol))
	admin.HandleFunc("/debug/pprof/trace", auth(nethttppprof.Trace))

	// 4) 仅监听 127.0.0.1，靠 sidecar/跳板机访问。
	go func() {
		log.Fatal(http.ListenAndServe("127.0.0.1:6060", admin))
	}()

	log.Fatal(http.ListenAndServe(":8080", businessMux()))
}

func auth(h http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		token := os.Getenv("PPROF_TOKEN")
		u, p, ok := r.BasicAuth()
		if token == "" || !ok || u != "ops" || p != token {
			http.Error(w, "forbidden", http.StatusForbidden)
			return
		}
		h(w, r)
	}
}

func businessMux() http.Handler { return http.NewServeMux() }
